item.command:
/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
     always@(posedge clk or negedge rst_n)begin
         if("'!rst_n) Q <= '"'d0;
-        else Q <= {~Q[1], Q[3 : 1]};
+        else Q <= {~Q[0], Q[3 : 1]};
     end
 endmodule
*** End Patch
PATCH

cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire [3:0] Q;

  TopModule dut(.clk(clk), .rst_n(rst_n), .Q(Q));

  always #5 clk = ~clk;

  initial begin
    "'$display("time rst_n Q");
    $monitor("%0t %b %b", $time, rst_n, Q);
    #2 rst_n = 0;
    #6 rst_n = 1;
    repeat (10) @(posedge clk);
    $finish;
  end
endmodule
EOF

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

